# Let's try to find the pattern more systematically
import os, re

def load():
    d = os.environ.get('RLM_SESSION_DIR', '')
    t = open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load()

def find_lines(grid):
    h = len(grid)
    v = len(grid[0])
    horiz = None
    vert = None
    for i in range(h):
        if all(grid[i][j] == 3 for j in range(v)):
            horiz = i
            break
    for j in range(v):
        if all(grid[i][j] == 3 for i in range(h)):
            vert = j
            break
    return horiz, vert

# Look at distances in Demo 2
d2_in = G['Demo pair 2 input']
d2_out = G['Demo pair 2 output']
h2, v2 = find_lines(d2_in)
print(f"Demo 2: H={h2}, V={v2}")

# Check distance to closest line for each cell
def compute_dist(i, j, h_line, v_line):
    dist_h = abs(i - h_line)
    dist_v = abs(j - v_line)
    return min(dist_h, dist_v)

print("\nDemo 2 top-left quadrant (rows 0-3, cols 0-5):")
for i in range(h2):
    row = []
    for j in range(v2):
        d = compute_dist(i, j, h2, v2)
        row.append(str(d))
    print(" ".join(row))

# Now compare with output
print("\nDemo 2 output values:")
for i in range(h2):
    for j in range(v2):
        print(f"({i},{j}): dist={compute_dist(i, j, h2, v2)}, val={d2_out[i][j]}")

